<?php
 namespace App\Console\Commands; use App\Services\Dapcode\CodeMinifierService; use App\Services\Dapcode\IntegrityService; use App\Services\Dapcode\LicenseGuard; use Illuminate\Console\Command; use Illuminate\Support\Str; class CodeMinifyCommand extends Command { protected $signature = 'code:minify {target=all : Target: "all", "modules", "aegisguard", "routes" (termasuk middleware, helper, kernel & portofolio), module name (e.g. "Achievement"), or custom path} {--no-backup : Skip storing original code in Secure SourceMap Vault} {--force : Force operation without confirmation}'; protected $description = 'Minify code (AegisGuard protection, HMVC modules, and Routes with Portfolio Homepage, Middlewares, Helpers & Kernel)'; public function handle(CodeMinifierService $minifier) { $target = (string) $this->argument('target'); $createBackup = !$this->option('no-backup'); $force = (bool) $this->option('force'); $this->info("======================================================="); $this->info("      DAPCODE AEGISGUARD — PHP CODE MINIFIER           "); $this->info("======================================================="); $displayTarget = $target; if (in_array(strtolower($target), ['routes', 'route', 'portfolio', 'home'], true)) { $displayTarget = "{$target} (Seluruh File Routes, Middlewares, Helpers & Halaman Utama Portofolio)"; } elseif (in_array(strtolower($target), ['aegisguard', 'protection', 'dapcode', 'enc', 'encrypted'], true)) { $displayTarget = "{$target} (Kode Proteksi AegisGuard & File Enkripsi .enc)"; } elseif (in_array(strtolower($target), ['middlewares', 'middleware'], true)) { $displayTarget = "{$target} (Seluruh File Middleware & Http/Kernel.php)"; } elseif (in_array(strtolower($target), ['helpers', 'helper'], true)) { $displayTarget = "{$target} (Seluruh File Helper)"; } elseif (in_array(strtolower($target), ['kernel', 'http-kernel'], true)) { $displayTarget = "{$target} (File Http/Kernel.php)"; } $this->line("<comment>Target     :</comment> <info>{$displayTarget}</info>"); $this->line("<comment>Vault Map  :</comment> " . ($createBackup ? '<info>Enabled (Secure SourceMap Vault)</info>' : '<comment>Disabled</comment>')); $this->newLine(); $files = $minifier->getTargetFiles($target); if (empty($files)) { $this->error("Tidak ada file PHP yang ditemukan untuk target [{$target}]."); return 1; } $this->line("Ditemukan <info>" . count($files) . "</info> file target."); if (!$force && count($files) > 10 && $this->input->isInteractive()) { if (!$this->confirm("Apakah Anda yakin ingin me-minify " . count($files) . " file PHP ini?", true)) { $this->warn("Operasi dibatalkan oleh pengguna."); return 0; } } $results = []; $totalOriginal = 0; $totalMinified = 0; $totalSaved = 0; $bar = $this->output->createProgressBar(count($files)); $bar->start(); foreach ($files as $file) { $res = $minifier->minifyFile($file, $createBackup); if ($res['success']) { $relPath = Str::after($file, base_path() . DIRECTORY_SEPARATOR); $totalOriginal += $res['original_size']; $totalMinified += $res['minified_size']; $totalSaved += $res['saved_bytes']; $typeLabel = '<comment>PHP</comment>'; if (Str::endsWith($file, '.blade.php')) { $typeLabel = '<info>Blade</info>'; } elseif (Str::endsWith($file, '.json')) { $typeLabel = '<fg=cyan>JSON</>'; } elseif (Str::endsWith($file, '.enc')) { $typeLabel = '<question>ENC</question>'; } $results[] = [ 'file' => $relPath, 'type' => $typeLabel, 'orig' => $this->formatBytes($res['original_size']), 'mini' => $this->formatBytes($res['minified_size']), 'saved' => $this->formatBytes($res['saved_bytes']) . " ({$res['saved_percent']}%)", ]; } $bar->advance(); } $bar->finish(); $this->newLine(2); $this->table( ['File Target', 'Type', 'Original', 'Minified', 'Saved'], $results ); $totalPercent = $totalOriginal > 0 ? round(($totalSaved / $totalOriginal) * 100, 2) : 0; $this->info("======================================================="); $this->info(" [SELESAI] " . count($results) . " file berhasil di-minify!"); $this->line(" Total Ukuran Awal    : <comment>" . $this->formatBytes($totalOriginal) . "</comment>"); $this->line(" Total Ukuran Minified: <info>" . $this->formatBytes($totalMinified) . "</info>"); $this->line(" Total Penghematan    : <info>" . $this->formatBytes($totalSaved) . " ({$totalPercent}%)</info>"); if ($createBackup) { $this->line(" Original tersimpan di <info>Secure SourceMap Vault</info> (terenkripsi & terisolasi)."); $this->line(" Untuk mengembalikan kode asli: <info>php artisan code:unminify {$target}</info>"); } $this->info("======================================================="); IntegrityService::recordCoreFilesManifest(); LicenseGuard::clearCache(); return 0; } protected function formatBytes($bytes, $precision = 2) { if ($bytes <= 0) { return '0 B'; } $units = ['B', 'KB', 'MB', 'GB']; $base = log($bytes, 1024); $pow = floor($base); return round(pow(1024, $base - $pow), $precision) . ' ' . ($units[$pow] ?? 'B'); } }